// Identifies this run and the 06:00/18:00 slot it serves (the same slots the trigger fires on).
const tz = $('Settings').first().json.timezone;
const now = DateTime.now().setZone(tz);
const probe = now.plus({ minutes: 5 });
let slot = null;
for (let d = 0; d < 2 && !slot; d++) {
  for (const h of [18, 6]) {
    const s = probe.minus({ days: d }).set({ hour: h, minute: 0, second: 0, millisecond: 0 });
    if (s <= probe) { slot = s; break; }
  }
}
return [{ json: { run_id: `run-${$execution.id}`, started_at: now.toUTC().toISO(), scheduled_for: slot.toUTC().toISO() } }];

// Health triage evaluation: a pure function of the Alertmanager snapshot, the stored issues, the
// previous run and the settings. It decides every transition and the one message; n8n nodes only
// read and write what it returns.

const SEVERITY_RANK = { none: 0, info: 1, warning: 2, critical: 3 };
// Labels that change between pods, scrape configs or metrics stores and so must not split an issue.
// k8s_cluster is folded into `cluster`; severity is compared, not identity; tier, capability and
// notify are rule metadata.
const DROPPED_LABELS = new Set([
  'alertname', 'k8s_cluster', 'prometheus', 'prometheus_replica', 'alertgroup', 'pod', 'instance',
  'endpoint', 'container', 'job', 'service', 'uid', 'severity', 'tier', 'capability', 'notify',
]);
const SIGNATURE_LABELS = ['reason', 'condition', 'phase'];
const IGNORED_ALERTS = new Set(['Watchdog', 'InfoInhibitor', 'CapabilityHeartbeat']);
const BLIND_ALERT = 'AlertPipelineBlind';
const HEARTBEAT_MISSING_ALERT = 'CapabilityHeartbeatMissing';
const ISSUE_COLUMNS = [
  'fingerprint', 'cluster', 'alertname', 'capability', 'tier', 'title', 'subject', 'status', 'severity',
  'signature', 'first_seen', 'last_seen', 'last_changed', 'resolved_at', 'runs_seen', 'absent_runs',
  'recurrences', 'root_cause_fp', 'last_notified_state', 'last_notified_at', 'labels_json',
  'annotations_json', 'alert_count', 'diagnosis_json', 'diagnosis_signature', 'diagnosed_at',
  'diagnosis_status',
];

function sha1(text) {
  const bytes = new TextEncoder().encode(text);
  const words = [];
  for (let i = 0; i < bytes.length; i++) words[i >> 2] |= bytes[i] << (24 - (i % 4) * 8);
  const bitLen = bytes.length * 8;
  words[bitLen >> 5] |= 0x80 << (24 - (bitLen % 32));
  words[(((bitLen + 64) >> 9) << 4) + 15] = bitLen;
  let [a, b, c, d, e] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];
  const rol = (x, n) => (x << n) | (x >>> (32 - n));
  for (let i = 0; i < words.length; i += 16) {
    const w = [];
    const [a0, b0, c0, d0, e0] = [a, b, c, d, e];
    for (let t = 0; t < 80; t++) {
      w[t] = t < 16 ? (words[i + t] | 0) : rol(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
      const f = t < 20 ? ((b & c) | (~b & d)) + 0x5a827999
        : t < 40 ? (b ^ c ^ d) + 0x6ed9eba1
          : t < 60 ? ((b & c) | (b & d) | (c & d)) + 0x8f1bbcdc
            : (b ^ c ^ d) + 0xca62c1d6;
      const tmp = (rol(a, 5) + f + e + w[t]) | 0;
      e = d; d = c; c = rol(b, 30); b = a; a = tmp;
    }
    a = (a + a0) | 0; b = (b + b0) | 0; c = (c + c0) | 0; d = (d + d0) | 0; e = (e + e0) | 0;
  }
  return [a, b, c, d, e].map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

const tierRank = (tier) => ({ H1: 1, H2: 2, H3: 3, M1: 4, M2: 5, M3: 6, L: 7 }[tier] || 7);
const tierClass = (tier) => (String(tier).startsWith('H') ? 'high' : String(tier).startsWith('M') ? 'medium' : 'low');

function normalize(alert, cfg) {
  const labels = alert.labels || {};
  const cluster = labels.k8s_cluster || 'homelab';
  const stable = {};
  for (const key of Object.keys(labels).sort()) {
    if (DROPPED_LABELS.has(key)) continue;
    let value = labels[key];
    if (key === 'replicaset') value = value.replace(/-[a-z0-9]{6,10}$/, '');
    if (key === 'job_name') value = value.replace(/-\d{6,}$/, '');
    stable[key] = value;
  }
  let capability = labels.capability || '';
  let tier = labels.tier || '';
  if (!capability || !tier) {
    const override = cfg.alertname_overrides.find(([pattern]) => new RegExp(pattern).test(labels.alertname));
    const byNamespace = cfg.namespaces[labels.namespace];
    if (override) {
      capability = capability || override[1];
      tier = tier || override[2];
    } else if (byNamespace) {
      capability = capability || byNamespace[0];
      tier = tier || byNamespace[1];
    }
    if (!tier && capability && cfg.capabilities[capability]) tier = cfg.capabilities[capability][0];
    tier = tier || 'L';
  }
  const fingerprint = sha1(JSON.stringify([cluster, labels.alertname, capability, stable]));
  const signature = [labels.alertname, ...SIGNATURE_LABELS.map((k) => labels[k] || '')].join('|');
  const subjectKey = ['namespace', 'name', 'pool', 'owner_name', 'node', 'pvc', 'volume', 'device']
    .find((k) => stable[k]);
  return {
    fingerprint, cluster, capability, tier, signature,
    alertname: labels.alertname,
    severity: labels.severity || 'warning',
    subject: subjectKey ? `${subjectKey} ${stable[subjectKey]}` : '',
    title: (alert.annotations && alert.annotations.summary) || labels.alertname,
    suppressed: !!(alert.status && alert.status.state === 'suppressed'),
    labels: { ...stable, alertname: labels.alertname, k8s_cluster: cluster },
    annotations: alert.annotations || {},
  };
}

function downstreamOf(capability, deps) {
  const seen = new Set();
  const walk = (c) => (deps[c] || []).forEach((d) => { if (!seen.has(d)) { seen.add(d); walk(d); } });
  walk(capability);
  return seen;
}

function emptyIssue(obs, now) {
  return {
    fingerprint: obs.fingerprint, cluster: obs.cluster, alertname: obs.alertname, capability: obs.capability,
    tier: obs.tier, title: obs.title, subject: obs.subject, status: 'open', severity: obs.severity,
    signature: obs.signature, first_seen: now, last_seen: now, last_changed: now, resolved_at: null,
    runs_seen: 0, absent_runs: 0, recurrences: 0, root_cause_fp: '', last_notified_state: '',
    last_notified_at: null, labels_json: '{}', annotations_json: '{}', alert_count: 0,
    diagnosis_json: '', diagnosis_signature: '', diagnosed_at: null, diagnosis_status: '',
  };
}

function evaluate({ cfg, now, runId, am, issues, prevRun }) {
  const byFp = new Map();
  for (const row of issues) if (row && row.fingerprint) byFp.set(row.fingerprint, { ...row });
  const changed = new Set();
  const events = [];
  const event = (fp, transition, detail) => {
    events.push({ ts: now, fingerprint: fp, run_id: runId, transition, detail: detail || '' });
    changed.add(fp);
  };
  const alerts = am.ok && Array.isArray(am.alerts) ? am.alerts : [];

  // 1. Is the pipeline from rules to Alertmanager to here working at all?
  let blindReason = '';
  if (!am.ok) {
    blindReason = `Alertmanager could not be read (${am.error || 'no response'})`;
  } else {
    const watchdogClusters = new Set(alerts
      .filter((a) => a.labels && a.labels.alertname === 'Watchdog')
      .map((a) => a.labels.k8s_cluster || 'homelab'));
    const missing = cfg.watchdog_clusters.filter((c) => !watchdogClusters.has(c));
    if (missing.length) blindReason = `Watchdog is missing for ${missing.join(', ')}`;
  }
  const blindObs = {
    fingerprint: sha1(JSON.stringify(['homelab', BLIND_ALERT, 'obs.alerting', {}])), cluster: 'homelab',
    alertname: BLIND_ALERT, capability: 'obs.alerting', tier: 'H1', severity: 'critical',
    signature: BLIND_ALERT, subject: '', suppressed: false, labels: { alertname: BLIND_ALERT },
    title: 'Alert pipeline blind: no alert can be trusted until Watchdog is back',
    annotations: { description: blindReason },
  };
  const touch = (obs) => {
    let row = byFp.get(obs.fingerprint);
    if (!row) {
      row = emptyIssue(obs, now);
      byFp.set(obs.fingerprint, row);
      event(obs.fingerprint, 'new', obs.title);
    } else if (row.status === 'resolved') {
      row.status = 'open';
      row.recurrences = (row.recurrences || 0) + 1;
      row.resolved_at = null;
      row.last_changed = now;
      event(obs.fingerprint, 'reopened', `recurrence ${row.recurrences}`);
    }
    return row;
  };

  if (blindReason) {
    const row = touch(blindObs);
    row.annotations_json = JSON.stringify(blindObs.annotations);
    row.last_seen = now;
    row.runs_seen = (row.runs_seen || 0) + 1;
    changed.add(row.fingerprint);
  } else {
    const blind = byFp.get(blindObs.fingerprint);
    if (blind && blind.status === 'open') {
      blind.status = 'resolved';
      blind.resolved_at = now;
      blind.last_changed = now;
      event(blind.fingerprint, 'resolved', 'Watchdog present again');
    }
  }

  // 2. Heartbeats: which capabilities' rules are evaluated.
  const seenHeartbeats = {};
  for (const a of alerts) {
    const l = a.labels || {};
    if (l.alertname === 'CapabilityHeartbeat' && l.capability) {
      seenHeartbeats[`${l.k8s_cluster || 'homelab'}/${l.capability}`] = l.tier || '';
    }
  }
  const observations = new Map();
  if (!blindReason) {
    let previous = {};
    try { previous = JSON.parse((prevRun && prevRun.heartbeats_json) || '{}'); } catch (e) { previous = {}; }
    const expected = new Map();
    for (const key of cfg.expected_heartbeats) expected.set(key, '');
    for (const [key, tier] of Object.entries(previous)) expected.set(key, tier);
    for (const row of byFp.values()) {
      if (row.alertname === HEARTBEAT_MISSING_ALERT && row.status !== 'resolved') {
        expected.set(`${row.cluster}/${row.capability}`, row.tier);
      }
    }
    for (const [key, knownTier] of expected) {
      if (key in seenHeartbeats) continue;
      const [cluster, capability] = key.split('/');
      const tier = knownTier || (cfg.capabilities[capability] || ['M2'])[0];
      const obs = normalize({
        labels: { alertname: HEARTBEAT_MISSING_ALERT, k8s_cluster: cluster, capability, tier, severity: 'warning' },
        annotations: { summary: `No ${capability} alert rules are being evaluated on ${cluster}` },
      }, cfg);
      observations.set(obs.fingerprint, { obs, alerts: [obs] });
    }

    // 3. Group the firing alerts into issues.
    for (const alert of alerts) {
      const l = alert.labels || {};
      if (IGNORED_ALERTS.has(l.alertname) || l.severity === 'none') continue;
      const obs = normalize(alert, cfg);
      const group = observations.get(obs.fingerprint);
      if (group) group.alerts.push(obs); else observations.set(obs.fingerprint, { obs, alerts: [obs] });
    }
  }

  // 4. State machine for everything present.
  for (const { obs, alerts: members } of observations.values()) {
    const severity = members.reduce((s, m) => (SEVERITY_RANK[m.severity] > SEVERITY_RANK[s] ? m.severity : s), 'none');
    const suppressed = members.every((m) => m.suppressed);
    const before = byFp.get(obs.fingerprint);
    const continuing = before && before.status !== 'resolved';
    const row = touch(obs);
    if (continuing && row.status === 'open') {
      if (SEVERITY_RANK[severity] > SEVERITY_RANK[row.severity]) {
        event(row.fingerprint, 'worsened', `${row.severity} -> ${severity}`);
        row.last_changed = now;
      } else if (row.signature !== obs.signature) {
        event(row.fingerprint, 'changed', `${row.signature} -> ${obs.signature}`);
        row.last_changed = now;
      }
    }
    if (suppressed && row.status !== 'accepted') {
      row.status = 'accepted';
      row.last_changed = now;
      event(row.fingerprint, 'accepted', 'silenced or inhibited in Alertmanager');
    } else if (!suppressed && row.status === 'accepted') {
      row.status = 'open';
      row.last_changed = now;
      event(row.fingerprint, 'unsilenced', 'no longer silenced or inhibited');
    }
    Object.assign(row, {
      tier: obs.tier, capability: obs.capability, title: obs.title, subject: obs.subject, severity,
      signature: obs.signature, last_seen: now, absent_runs: 0, runs_seen: (row.runs_seen || 0) + 1,
      alert_count: members.length, labels_json: JSON.stringify(obs.labels),
      annotations_json: JSON.stringify(obs.annotations),
    });
    changed.add(row.fingerprint);
  }

  // 5. Resolution: absent from two consecutive trustworthy snapshots whose heartbeat was present.
  if (!blindReason) {
    for (const row of byFp.values()) {
      if (row.status === 'resolved' || observations.has(row.fingerprint) || row.alertname === BLIND_ALERT) continue;
      const heartbeatKey = `${row.cluster}/${row.capability}`;
      const expectsHeartbeat = cfg.expected_heartbeats.includes(heartbeatKey) || heartbeatKey in seenHeartbeats;
      if (row.alertname !== HEARTBEAT_MISSING_ALERT && row.capability && expectsHeartbeat && !(heartbeatKey in seenHeartbeats)) {
        continue; // unobservable: its rules are not being evaluated, so absence proves nothing
      }
      row.absent_runs = (row.absent_runs || 0) + 1;
      changed.add(row.fingerprint);
      if (row.absent_runs >= 2) {
        row.status = 'resolved';
        row.resolved_at = now;
        row.last_changed = now;
        event(row.fingerprint, 'resolved', 'absent from two consecutive snapshots');
      }
    }
  }

  // 6. Dependency collapse: an issue whose upstream capability is also open is attributed to it.
  const live = [...byFp.values()].filter((r) => r.status === 'open');
  for (const row of live) {
    const upstream = live
      .filter((u) => u !== row && u.cluster === row.cluster && u.capability
        && downstreamOf(u.capability, cfg.dependencies).has(row.capability))
      .sort((x, y) => tierRank(x.tier) - tierRank(y.tier) || String(x.first_seen).localeCompare(String(y.first_seen)))[0];
    const rootCause = upstream ? upstream.fingerprint : '';
    if (row.root_cause_fp !== rootCause) {
      row.root_cause_fp = rootCause;
      changed.add(row.fingerprint);
      if (rootCause) event(row.fingerprint, 'attributed', `likely consequence of ${upstream.title}`);
    }
  }
  for (const row of byFp.values()) {
    if (row.status !== 'open' && row.root_cause_fp) { row.root_cause_fp = ''; changed.add(row.fingerprint); }
  }

  // 7. Gate: decide what the user is told.
  const independent = live.filter((r) => !r.root_cause_fp);
  const highOpen = independent.some((r) => tierClass(r.tier) === 'high');
  const items = [];
  for (const row of byFp.values()) {
    const cls = tierClass(row.tier);
    const last = row.last_notified_state || '';
    let state;
    let label;
    if (row.status === 'open') {
      if (row.root_cause_fp) continue;
      if (cls === 'low' || (cls === 'medium' && highOpen)) continue;
      state = `open|${row.severity}|${row.signature}`;
      if (state === last) continue;
      if (!last || last === 'resolved') {
        label = row.recurrences > 0 ? 'BACK' : 'NEW';
        if (row.recurrences > cfg.max_reopen_notifications) {
          row.last_notified_state = state; // recorded, not announced
          changed.add(row.fingerprint);
          continue;
        }
      } else {
        label = last.split('|')[1] !== row.severity ? 'WORSE' : 'CHANGED';
      }
    } else if (row.status === 'resolved') {
      if (!last.startsWith('open')) continue;
      state = 'resolved';
      label = 'RESOLVED';
    } else {
      continue;
    }
    row.last_notified_state = state;
    row.last_notified_at = now;
    changed.add(row.fingerprint);
    items.push({ row, label });
  }

  // 8. The message: problem, impact, blast radius and the page link. Nothing else.
  let message = null;
  if (items.length) {
    const order = { NEW: 0, BACK: 1, WORSE: 2, CHANGED: 3, RESOLVED: 4 };
    // Alerts that differ only by an instance-like label (one per address pool, per job) read as one
    // problem, so they share one entry.
    const entries = new Map();
    for (const item of items) {
      const r = item.row;
      const key = [item.label, r.tier, r.cluster, r.capability, r.subject, r.alertname === BLIND_ALERT ? r.fingerprint : ''].join('|');
      if (!entries.has(key)) entries.set(key, { label: item.label, rows: [] });
      entries.get(key).rows.push(r);
    }
    const sorted = [...entries.values()].sort((x, y) => tierRank(x.rows[0].tier) - tierRank(y.rows[0].tier)
      || order[x.label] - order[y.label]);
    const lines = [];
    for (const { label, rows } of sorted.slice(0, cfg.max_items)) {
      const row = rows[0];
      const where = [row.cluster, row.subject].filter(Boolean).join(', ');
      const title = rows.length > 1 ? `${row.title} (+${rows.length - 1} similar)` : row.title;
      if (label === 'RESOLVED') {
        lines.push(`RESOLVED [${row.tier}] ${title} (${where})`);
        continue;
      }
      const impact = row.alertname === BLIND_ALERT
        ? `${JSON.parse(row.annotations_json || '{}').description || ''}. Nothing else is evaluated until it is back.`
        : row.alertname === HEARTBEAT_MISSING_ALERT
          ? `If ${row.capability} breaks, no alert will fire. At stake: ${(cfg.capabilities[row.capability] || [null, 'not catalogued'])[1]}`
          : (cfg.capabilities[row.capability] || [null, 'Impact not catalogued for this alert.'])[1];
      const attached = live.filter((r) => rows.some((x) => r.root_cause_fp === x.fingerprint)).length;
      const downstream = [...downstreamOf(row.capability, cfg.dependencies)];
      const blast = row.alertname === BLIND_ALERT ? `every alert on ${row.cluster}` : [downstream.length ? `depends on it: ${downstream.join(', ')}` : 'no dependent capabilities',
        attached ? `${attached} related issue(s) attached` : ''].filter(Boolean).join('; ');
      const link = rows.length > 1 ? `${cfg.page_base_url}/issues` : `${cfg.page_base_url}/issue?fp=${row.fingerprint}`;
      lines.push(`${label} [${row.tier}] ${title} (${where})\nImpact: ${impact}\nBlast radius: ${blast}\n${link}`);
    }
    if (sorted.length > cfg.max_items) lines.push(`+${sorted.length - cfg.max_items} more: ${cfg.page_base_url}/issues`);
    const shown = new Set(items.map((i) => i.row.fingerprint));
    const held = { medium: 0, low: 0 };
    for (const r of independent) {
      if (!shown.has(r.fingerprint) && tierClass(r.tier) !== 'high') held[tierClass(r.tier)] += 1;
    }
    if (!blindReason && (held.medium || held.low)) lines.push(`Also open, not shown: ${held.medium} medium, ${held.low} low.`);
    message = lines.join('\n\n');
  }

  const counts = { open: { high: 0, medium: 0, low: 0 }, accepted: 0, attributed: 0, new: 0, resolved: 0 };
  for (const r of byFp.values()) {
    if (r.status === 'open') counts.open[tierClass(r.tier)] += 1;
    if (r.status === 'accepted') counts.accepted += 1;
    if (r.status === 'open' && r.root_cause_fp) counts.attributed += 1;
  }
  for (const e of events) {
    if (e.transition === 'new') counts.new += 1;
    if (e.transition === 'resolved') counts.resolved += 1;
  }
  const issueRows = [...changed].map((fp) => {
    const row = byFp.get(fp);
    return Object.fromEntries(ISSUE_COLUMNS.map((c) => [c, row[c] === undefined ? null : row[c]]));
  });
  return {
    issueRows,
    events,
    message,
    run: {
      status: blindReason ? 'blind' : 'ok',
      watchdog: !blindReason,
      notified: !!message,
      counts_json: JSON.stringify(counts),
      // A blind run saw nothing, so it keeps the previous run's heartbeats as the expectation.
      heartbeats_json: blindReason ? ((prevRun && prevRun.heartbeats_json) || '{}') : JSON.stringify(seenHeartbeats),
      message: message || '',
    },
  };
}


// n8n wiring: everything above is a pure function of these inputs.
const cfg = $('Settings').first().json;
const ctx = $('Run Context').first().json;
const resp = $('Alertmanager').first().json;
let am;
if (resp.error) {
  let reason = String(resp.error.message || resp.error.code || JSON.stringify(resp.error));
  try { const parsed = JSON.parse(reason); reason = parsed.description || parsed.message || reason; } catch (e) { /* plain text */ }
  am = { ok: false, error: reason.slice(0, 200) };
} else {
  try {
    const alerts = JSON.parse(resp.data);
    am = Array.isArray(alerts) ? { ok: true, alerts } : { ok: false, error: 'response is not an alert list' };
  } catch (e) {
    am = { ok: false, error: `unparseable response: ${e.message}` };
  }
}
const issues = $('Get Issues').all().map((i) => i.json).filter((r) => r.fingerprint);
const prevRun = $('Get Last Run').all().map((i) => i.json).find((r) => r.run_id) || null;
return [{ json: evaluate({ cfg, now: ctx.started_at, runId: ctx.run_id, am, issues, prevRun }) }];
